int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags) {
    int ret;
    long timeo;

    if (msg_flags & MSG_DONTWAIT)
        timeo = 0;
    else if (msg_flags & MSG_WAITALL)
        timeo = MAX_SCHEDULE_TIMEOUT;
    else
        timeo = sock->sk->sk_rcvtimeo;

    while (1) {
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);

        if (ret >= 0 || ret != -EAGAIN) {
            break;
        }

        if (timeo <= 0) {
            ret = -EAGAIN;
            break;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            break;
        }

        timeo = schedule_timeout(timeo);
    }

    if (ret > 0) {
        msg->msg_flags = msg_flags;
        sock_update_read_counts(sock, ret);
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags)
{
    int ret;
    unsigned int flags = msg_flags;
    struct sock *sk = sock->sk;

    if (sk->sk_state == TCP_LISTEN)
        return -EOPNOTSUPP;

    if (size > SSIZE_MAX)
        size = SSIZE_MAX;

    ret = sock->ops->recvmsg(iocb, sock, msg, size, flags, &msg->msg_flags);
    if (ret > 0)
        sock_update_rcvtime(sk, sock);
    return ret;
}

int recvmsg_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    int result;
    long timeout = 0;
    struct sock *sk = sock->sk;

    while (1) {
        result = sock_recvmsg(sock, msg, size, msg_flags);
        if (result > 0) {
            iocb->ki_nbytes = result;
            sk->sk_stat.bytes_received += result;
            break;
        } else if (result == -EAGAIN) {
            if (msg_flags & MSG_DONTWAIT) {
                break;
            }
            if (timeout == 0) {
                timeout = iocb->ki_timeout;
            }
            schedule_timeout(timeout);
            continue;
        } else {
            break;
        }
    }

    return result;
}

int recvmsg_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    int ret;
    struct sock *sk = sock->sk;

    if (unlikely(!(msg_flags & MSG_DONTWAIT) && (sk->sk_state & (1 << sock_iocb_state_pending)) )) {
        return -EAGAIN;
    }

    do {
        ret = sock_recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret > 0) {
            msg->msg_flags = 0;
            if (msg->msg_iovlen > 0) {
                msg->msg_iov[0].iov_len -= ret;
                msg->msg_iov[0].iov_base = (char *)msg->msg_iov[0].iov_base + ret;
            }
            sk->sk_stat_bytes_received += ret;
        }
    } while (ret == -EAGAIN && !(msg_flags & MSG_DONTWAIT));

    return ret;
}
